style.css:
@-moz-document domain("instagram.com") {
/* 1. Main Background and Container */
  body, .x9f619, .x1n2onr6, .x78zum5 {
    background-color: #fff0f3 !important;
  }

  /* 2. Navigation Bar */
  .xvb8j5, [role="navigation"] {
    background-color: #ffe6eb !important;
    border-right: 1px solid #ffccd5 !important;
  }

  /* 3. Main Feed Posts */
  article, .x1cy8zhl {
    background-color: #ffffff !important;
    border: 1px solid #ffccd5 !important;
    border-radius: 12px !important;
    box-shadow: 0 4px 12px rgba(255, 117, 140, 0.08) !important;
  }

  /* 4. Action Buttons (Follow, Log In, Blue Buttons) */
  ._acap, ._acan, ._acap, button[type="button"] {
    background-color: #ff758c !important;
    color: #ffffff !important;
    border-radius: 8px !important;
  }
  ._acap:hover, ._acan:hover {
    background-color: #ff477e !important;
  }

  /* 5. Text, Links, and Icons */
  span, a, h1, h2, h3, p, svg {
    color: #4a2832 !important;
    fill: #4a2832 !important;
  }

  /* 6. Instagram Gradient Story Rings (Pink/Rose gold vibe) */
  .x1vjfegm, ._aame {
    background: linear-gradient(45deg, #ff477e, #ff758c, #ffb3c1) !important;
  }

  /* 7. Search and Direct Message Inputs */
  input, .x1ior59r {
    background-color: #fff0f3 !important;
    border: 1px solid #ffccd5 !important;
    color: #4a2832 !important;
    border-radius: 8px !important;
  }
}
